import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.eclipse.rdf4j.query.impl.ListBindingSet;
import org.eclipse.rdf4j.query.parser.QueryParserUtil;
import org.junit.jupiter.api.Test;

public class OrderLimitOptimizerTest extends QueryOptimizerTest {

	@Test
	public void orderingProjectedAliasSurvivesNestedProjection() throws Exception {
		String query = "SELECT ?alias WHERE { { SELECT (?value AS ?alias) WHERE { VALUES ?value { 2 1 } } "
				+ "ORDER BY ?alias } } ORDER BY ?alias";

		assertThat(orderedValues(query, "alias", false)).containsExactly("1", "2");
		assertThat(orderedValues(query, "alias", true)).containsExactly("1", "2");
	}

	@Test
	public void orderKeyOutsideProjectionRemainsAvailableForSorting() throws Exception {
		String query = "SELECT ?label WHERE { VALUES (?sort ?label) { (2 \"b\") (1 \"a\") } } ORDER BY ?sort";

		assertThat(orderedValues(query, "label", false)).containsExactly("a", "b");
		assertThat(orderedValues(query, "label", true)).containsExactly("a", "b");
	}

	@Test
	public void keepsUnprovenEffectfulOrderExpressionWithinProjection() {
		Projection projection = new Projection(new Order(new SingletonSet(),
				new OrderElem(new FunctionCall("urn:custom:effectful"))),
				new ProjectionElemList(new ProjectionElem("selected")));
		QueryRoot original = new QueryRoot(projection);
		QueryRoot optimized = original.clone();

		new OrderLimitOptimizer().optimize(optimized, null, EmptyBindingSet.getInstance());

		assertThat(optimized).isEqualTo(original);
	}

	@Test
	public void orderByInputNameDoesNotUseProjectedAliasValue() throws Exception {
		BindingSetAssignment rows = new BindingSetAssignment();
		rows.setBindingNames(Set.of("source", "alias"));
		rows.setBindingSets(new ArrayList<>(List.of(
				new ListBindingSet(List.of("source", "alias"), SimpleValueFactory.getInstance().createLiteral("b"),
						SimpleValueFactory.getInstance().createLiteral("a")),
				new ListBindingSet(List.of("source", "alias"), SimpleValueFactory.getInstance().createLiteral("a"),
						SimpleValueFactory.getInstance().createLiteral("b")))));
		Projection projection = new Projection(new Order(rows, new OrderElem(Var.of("alias"))),
				new ProjectionElemList(new ProjectionElem("source", "alias")));
		QueryRoot original = new QueryRoot(projection);
		List<String> expected = orderedValues(original.clone(), "alias");
		assertThat(expected).containsExactly("b", "a");

		QueryRoot optimized = original.clone();
		new OrderLimitOptimizer().optimize(optimized, null, EmptyBindingSet.getInstance());

		assertThat(orderedValues(optimized, "alias")).containsExactlyElementsOf(expected);
	}

	private static List<String> orderedValues(String query, String resultName, boolean optimize) throws Exception {
		TupleExpr expression = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
		if (optimize) {
			new OrderLimitOptimizer().optimize(expression, null, EmptyBindingSet.getInstance());
		}

		return orderedValues(expression, resultName);
	}

	private static List<String> orderedValues(TupleExpr expression, String resultName) throws Exception {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		List<String> values = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = strategy.evaluate(expression, EmptyBindingSet.getInstance())) {
			while (iteration.hasNext()) {
				values.add(iteration.next().getValue(resultName).stringValue());
			}
		}
		return values;
	}

	@Override
	public QueryOptimizer getOptimizer() {
		return new OrderLimitOptimizer();
	}

}
